insert into public.modules (id,name,intro,color,coach_angle,position) values ('s','Structurer','Savoir ce que l’on veut dire, puis le dire dans le bon ordre.','#1d4ed8','Angle : structure et clarté (message en une phrase, accroche, plan en trois temps, histoire, chute). Inspiration : l’approche d’un ancien journaliste devenu formateur : aller à l’essentiel, être compris du premier coup.',1) on conflict (id) do update set name=excluded.name,intro=excluded.intro,color=excluded.color,coach_angle=excluded.coach_angle,position=excluded.position;
insert into public.modules (id,name,intro,color,coach_angle,position) values ('e','Faire entendre','Le souffle, la voix, le rythme : ce qui rend un texte vivant à l’oral.','#b4235a','Angle : éloquence orale (souffle, pauses, phrases courtes, mots concrets, rythme, mots parasites, gestion du trac). Inspiration : la tradition des concours d’éloquence et du barreau.',2) on conflict (id) do update set name=excluded.name,intro=excluded.intro,color=excluded.color,coach_angle=excluded.coach_angle,position=excluded.position;
insert into public.modules (id,name,intro,color,coach_angle,position) values ('a','Analyser','Comprendre comment un discours persuade, pour mieux construire le sien et mieux écouter celui des autres.','#0f766e','Angle : analyse du discours (ethos, pathos, logos, sophismes, cadrage des mots, usage des chiffres, questions piège). Inspiration : l’analyse politique du discours.',3) on conflict (id) do update set name=excluded.name,intro=excluded.intro,color=excluded.color,coach_angle=excluded.coach_angle,position=excluded.position;
insert into public.modules (id,name,intro,color,coach_angle,position) values ('m','Mises en situation','Entretien, réunion, pitch, cérémonie, débat : s’entraîner aux moments qui comptent.','#b45309','Angle : mise en situation réelle. Évalue l’adéquation au public et à l’objectif, la clarté de la demande, la crédibilité, le respect des usages du contexte (y compris sénégalais si le texte s’y rapporte) et la durée.',4) on conflict (id) do update set name=excluded.name,intro=excluded.intro,color=excluded.color,coach_angle=excluded.coach_angle,position=excluded.position;
insert into public.modules (id,name,intro,color,coach_angle,position) values ('d','Défis chronométrés','Improviser sous la contrainte du temps : la meilleure préparation aux imprévus.','#6d28d9','Angle : improvisation chronométrée. Évalue la tenue du temps (durée estimée comparée à la cible), une structure rapide (point, raison, exemple, retour au point), la concision et la force de la première et de la dernière phrase.',5) on conflict (id) do update set name=excluded.name,intro=excluded.intro,color=excluded.color,coach_angle=excluded.coach_angle,position=excluded.position;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('s1','s',1,'Un message, une phrase',false,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('s1','["Avant d’écrire un mot, formulez ce que le public doit retenir en une seule phrase. Si vous ne pouvez pas la dire en quinze secondes, votre message n’est pas encore clair.", "Tout le reste du discours sert cette phrase : ce qui ne la sert pas se coupe, même si c’est intéressant."]'::jsonb,'Écrivez le message de votre prochaine prise de parole en une phrase, puis les trois idées qui le soutiennent.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('s2','s',2,'Les vingt premières secondes',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('s2','["Le public décide très vite s’il vous écoute. Ouvrez avec une question, un fait précis ou une image concrète, jamais avec des excuses ni un « bonjour, je vais vous parler de ».", "Apprenez votre ouverture par cœur et dites-la sans notes, à voix haute, en regardant le public."]'::jsonb,'Écrivez trois ouvertures différentes (une question, un fait, une image) pour le même sujet.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('s3','s',3,'Le plan en trois temps',true,90) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('s3','["Annoncez où vous allez, déroulez, puis terminez par une chute : une phrase qui referme la boucle ouverte au début.", "Trois parties suffisent presque toujours. Au-delà, le public ne suit plus et vous non plus."]'::jsonb,'Rédigez un discours de 90 secondes : annonce, deux arguments, chute.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('s4','s',4,'Raconter une histoire courte',true,90) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('s4','["Une histoire bien racontée se retient mieux qu’une liste d’arguments. Le schéma le plus simple : une situation, un obstacle, ce que l’on a fait, ce que l’on en a appris.", "Choisissez un détail concret (un lieu, une heure, une phrase entendue) : c’est lui qui fait voir la scène. Coupez tout ce qui ne mène pas à la leçon."]'::jsonb,'Racontez en 150 mots maximum une anecdote de votre vie professionnelle selon le schéma situation, obstacle, action, leçon.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('s5','s',5,'Finir fort',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('s5','["La dernière phrase est celle que le public emporte. « Voilà, c’est tout, merci » gaspille ce moment.", "Trois fins qui fonctionnent : un appel à l’action précis, un retour à l’image du début, une phrase courte qui résume le message."]'::jsonb,'Pour le même sujet, écrivez trois conclusions : un appel à l’action, un retour à l’ouverture, une phrase-résumé.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('e1','e',1,'Respirer avant de parler',false,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('e1','["Une pause de deux secondes avant la première phrase vous donne de l’autorité et le temps de respirer. Inspirez par le ventre, expirez lentement.", "Le silence n’est pas un vide : c’est ce qui laisse une phrase atteindre le public."]'::jsonb,'Écrivez un paragraphe de cinq phrases et marquez d’un « / » chaque endroit où vous marquerez une pause.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('e2','e',2,'Phrases courtes, mots concrets',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('e2','["À l’oral, on ne peut pas relire. Préférez des phrases d’une quinzaine de mots, des verbes d’action et des exemples que l’on peut se représenter.", "Lisez votre texte à voix haute : là où vous butez, réécrivez."]'::jsonb,'Réécrivez un paragraphe abstrait de votre travail en phrases courtes, avec au moins un exemple concret.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('e3','e',3,'Rythme et conviction',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('e3','["Variez le rythme : ralentissez sur l’idée clé, accélérez sur le détail. Répéter un mot ou une structure crée une cadence qui marque les esprits.", "La conviction vient de la préparation : on ne convainc pas avec un texte que l’on découvre en le lisant."]'::jsonb,'Écrivez une conclusion de six phrases où un mot ou une structure revient trois fois.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('e4','e',4,'Chasser les mots parasites',true,60) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('e4','["« Euh », « voilà », « en fait », « donc », « genre » : ces mots remplissent le silence parce qu’on en a peur. Ils affaiblissent l’autorité de celui qui parle.", "Le remède n’est pas de se surveiller sans cesse, mais de remplacer le mot parasite par une courte pause. Enregistrez-vous une minute et comptez-les : la prise de conscience fait déjà la moitié du travail."]'::jsonb,'Écrivez une présentation de vous-même d’une minute, telle que vous la diriez spontanément, puis listez vos mots parasites habituels et ce que vous ferez à leur place.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('e5','e',5,'Apprivoiser le trac',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('e5','["Le trac est normal : c’est de l’énergie. Il diminue avec la préparation et avec une routine fixe avant de parler.", "Une routine simple : arriver tôt, repérer la salle, respirer lentement, boire de l’eau, se répéter la première phrase. Les deux premières phrases apprises par cœur portent tout le reste."]'::jsonb,'Écrivez votre routine d’avant prise de parole en cinq étapes, puis les deux premières phrases que vous apprendrez par cœur.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('a1','a',1,'Ethos, pathos, logos',false,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('a1','["Un discours persuade par trois leviers : la crédibilité de celui qui parle (ethos), l’émotion suscitée (pathos) et la solidité des arguments (logos).", "Repérez lequel domine dans un discours que vous écoutez, et lequel manque dans le vôtre."]'::jsonb,'Prenez un discours public récent et décrivez en huit lignes quel levier domine, avec deux exemples.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('a2','a',2,'Repérer un sophisme',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('a2','["Quelques pièges classiques : l’homme de paille (déformer l’argument adverse), la pente glissante (prédire une catastrophe sans preuve), le faux dilemme (n’offrir que deux options).", "Nommer le procédé permet de répondre calmement plutôt que de subir."]'::jsonb,'Écrivez un court argument contenant un faux dilemme, puis réécrivez-le sans le piège.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('a3','a',3,'Cadrer le débat',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('a3','["Les mots choisis installent un cadre : parler de « charges » ou de « cotisations » ne dit pas la même chose. Celui qui impose le cadre oriente la discussion.", "Avant de répondre, demandez-vous quel cadre votre interlocuteur vous propose, et si vous l’acceptez."]'::jsonb,'Choisissez un sujet de débat et écrivez deux phrases décrivant le même fait avec deux cadres opposés.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('a4','a',4,'Les chiffres qui parlent',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('a4','["Un chiffre seul ne dit rien au public. Rapportez-le à quelque chose de connu : une comparaison, une échelle humaine, une évolution dans le temps.", "Un chiffre par idée suffit. Citez sa source : c’est ce qui le rend crédible, et c’est ce qu’un contradicteur vous demandera."]'::jsonb,'Prenez un chiffre de votre activité et présentez-le de trois façons : en comparaison, à l’échelle d’une personne, en évolution.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('a5','a',5,'Répondre à une question piège',true,null) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('a5','["Une question piège contient souvent une affirmation cachée. Repérez-la avant de répondre : vous n’êtes pas obligé de l’accepter.", "Méthode en quatre temps : reformuler calmement, nommer ce que la question suppose, répondre à la vraie question, revenir à votre message."]'::jsonb,'Écrivez une question hostile que l’on pourrait vous poser dans votre métier, puis votre réponse en quatre temps.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m1','m',1,'Se présenter en 60 secondes',false,60) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m1','["Une bonne présentation répond à quatre questions : qui je suis, ce que j’apporte, une preuve, ce que je cherche.", "Évitez la liste de diplômes : une réalisation concrète vaut plus que trois titres."]'::jsonb,'Écrivez votre présentation d’une minute selon les quatre questions.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m2','m',2,'L’entretien d’embauche',true,120) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m2','["À « Parlez-moi d’une réussite », répondez avec une situation précise, l’action que vous avez menée vous-même et le résultat mesurable.", "Préparez trois histoires de ce type à l’avance : elles répondent à la plupart des questions d’entretien."]'::jsonb,'Répondez en deux minutes à « Parlez-moi d’une réussite dont vous êtes fier » selon le schéma situation, action, résultat.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m3','m',3,'Intervenir en réunion',true,45) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m3','["En réunion, on a rarement plus de quarante-cinq secondes d’attention. Dites d’abord ce que vous proposez, ensuite pourquoi, enfin ce que vous attendez des autres.", "Terminez par une demande claire : une décision, une date, un responsable."]'::jsonb,'Rédigez une intervention de 45 secondes qui propose une solution à un problème de votre équipe et se termine par une demande précise.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m4','m',4,'Le pitch',true,90) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m4','["Un pitch suit un fil simple : le problème, votre solution, la preuve que ça marche, ce que vous demandez.", "Parlez du client avant de parler de vous. Un chiffre ou un témoignage vaut mieux que trois adjectifs."]'::jsonb,'Rédigez le pitch de 90 secondes d’un projet ou d’une entreprise que vous portez.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m5','m',5,'Le discours de circonstance',true,120) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m5','["Mariage, baptême, départ à la retraite, hommage : on vous attend sur l’émotion juste et la brièveté. Saluez selon les usages, honorez la personne par une anecdote vraie, terminez par un vœu ou un remerciement.", "Deux minutes suffisent. Un discours de circonstance trop long fatigue même ceux qui aiment la personne."]'::jsonb,'Écrivez un discours de deux minutes pour une cérémonie de votre choix (mariage, baptême, départ, hommage).') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('m6','m',6,'Le débat contradictoire',true,90) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('m6','["Avant de réfuter, reformulez loyalement l’argument adverse : le public vous fait confiance quand il voit que vous l’avez compris.", "Ensuite : concédez ce qui est juste, réfutez le point faible avec un fait, concluez sur votre position."]'::jsonb,'Choisissez une position avec laquelle vous n’êtes pas d’accord et rédigez une réponse de 90 secondes : reformulation, concession, réfutation, conclusion.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('d1','d',1,'Improviser en 60 secondes',false,60) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('d1','["Pour improviser sans se perdre : une idée, une raison, un exemple, puis on revient à l’idée. Quatre temps, une minute.", "Tirez un sujet au hasard, prenez dix secondes pour choisir votre idée, lancez le chronomètre et écrivez comme vous parleriez."]'::jsonb,'Tirez un sujet au hasard et répondez en une minute : idée, raison, exemple, retour à l’idée.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('d2','d',2,'Expliquer simplement',true,90) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('d2','["Si vous ne pouvez pas expliquer votre métier à un enfant de douze ans, vous ne le maîtrisez pas encore à l’oral.", "Utilisez une comparaison avec la vie quotidienne et bannissez le jargon."]'::jsonb,'Expliquez en 90 secondes un concept de votre métier à un enfant de douze ans, avec une comparaison.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('d3','d',3,'Convaincre en deux minutes',true,120) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('d3','["Une position, deux arguments, une objection traitée : c’est la structure minimale pour convaincre vite.", "Traiter l’objection avant qu’on vous la fasse montre que vous avez réfléchi."]'::jsonb,'Tirez un sujet au hasard, prenez position et convainquez en deux minutes, en traitant une objection.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.lessons (id,module_id,position,title,premium,duration_sec) values ('d4','d',4,'L’ascenseur',true,30) on conflict (id) do update set module_id=excluded.module_id,position=excluded.position,title=excluded.title,premium=excluded.premium,duration_sec=excluded.duration_sec;
insert into public.lesson_content (lesson_id,body,task) values ('d4','["Trente secondes pour obtenir un rendez-vous : qui vous êtes, le problème que vous réglez, la demande.", "Ne cherchez pas à tout dire : cherchez à obtenir la suite de la conversation."]'::jsonb,'Rédigez votre présentation d’ascenseur de 30 secondes destinée à un décideur que vous rêvez de rencontrer.') on conflict (lesson_id) do update set body=excluded.body,task=excluded.task;
insert into public.plans (id,label,amount,days,position) values ('mois','1 mois',5000,30,1) on conflict (id) do nothing;
insert into public.plans (id,label,amount,days,position) values ('trimestre','3 mois',12000,90,2) on conflict (id) do nothing;
insert into public.plans (id,label,amount,days,position) values ('annee','12 mois',40000,365,3) on conflict (id) do nothing;
